def word_break(s, word_dict):
    words = set(word_dict)
    memo = {}

    def break_from(start):
        if start in memo:
            return memo[start]
        if start == len(s):
            return ['']
        sentences = []
        for end in range(start + 1, len(s) + 1):
            piece = s[start:end]
            if piece in words:
                for rest in break_from(end):
                    sentences.append(piece if not rest else piece + ' ' + rest)
        memo[start] = sentences
        return sentences

    return sorted(break_from(0))

